-- raylib.lua: tmg glue for the raylib-luajit-generated submodule
-- (lib/raylib-luajit-generated).
--
-- The binding (raylib/init.lua, generated by raylib/generate.lua) assumes it
-- is run from its own repo root:
--   * it reads "raylib/generated.h" relative to the current directory
--   * it ffi.load()s "libraylib" and "libphysac" through the system loader only
-- This module makes `require("raylib")` work from any directory without
-- touching the submodule:
--   * generated.h is resolved inside the submodule
--   * libraylib / libphysac are looked up in TMG_LIB_PATH, then in the
--     binding's raylib/ dir and root, and only then in the system paths
--   * libphysac is optional: when missing, physac functions are left out
--
-- Use:  TMG_LIB_PATH=/path/to/tmg/lib:/dir/with/libraylib tmg main.lua
--       local rl = require("raylib")
--
-- The submodule location can be overridden with RAYLIB_LUAJIT_DIR.

local ffi = require("ffi")

local real_open, real_load = io.open, ffi.load

local here = debug.getinfo(1, "S").source:match("^@(.*)[/\\][^/\\]*$") or "."
local root = os.getenv("RAYLIB_LUAJIT_DIR") or (here .. "/raylib-luajit-generated")

local init = root .. "/raylib/init.lua"
local probe = real_open(init, "r")
if not probe then
    error("raylib: cannot find " .. init .. "\n"
          .. "  is the submodule checked out?  git submodule update --init --recursive", 0)
end
probe:close()

local ext = (ffi.os == "OSX" and ".dylib") or (ffi.os == "Windows" and ".dll") or ".so"

-- "libraylib" -> first existing <dir>/libraylib<ext> in:
--   TMG_LIB_PATH dirs, <root>/raylib, <root>
local function locate(name)
    local dirs = {}
    for _, d in ipairs(type(tmg) == "table" and tmg.lib_path or {}) do dirs[#dirs + 1] = d end
    dirs[#dirs + 1] = root .. "/raylib"
    dirs[#dirs + 1] = root
    for _, d in ipairs(dirs) do
        for _, base in ipairs({ name, "lib" .. name }) do
            local p = d .. "/" .. base .. ext
            local f = real_open(p, "rb")
            if f then f:close(); return p end
        end
    end
end

-- libphysac is optional: stub the module out instead of failing the require
if not locate("libphysac") and not pcall(real_load, "libphysac") then
    io.stderr:write("raylib: libphysac not found, physac functions are disabled\n")
    package.preload["raylib.physac"] = function() return function(rl) return rl end end
end

-- raylib.raygui / raylib.physac live next to init.lua
package.path = root .. "/?.lua;" .. root .. "/?/init.lua;" .. package.path

-- redirect the two cwd/system-dependent calls, only while init.lua loads
ffi.load = function(name, ...)
    local p = type(name) == "string" and not name:find("[/\\]") and locate(name)
    return real_load(p or name, ...)
end
io.open = function(path, mode)
    if path == "raylib/generated.h" then path = root .. "/" .. path end
    return real_open(path, mode)
end

local ok, rl = pcall(assert(loadfile(init)))
ffi.load, io.open = real_load, real_open
if not ok then error(rl, 0) end
return rl
